from pathlib import Path
import subprocess,uuid,json,hashlib
root=Path(__file__).resolve().parent.parent
binary=Path(r'D:\SteamLibrary\steamapps\common\SourceFilmmaker\game\bin\shaderapidx9.dll')
source=json.loads((root/'outputs/sfm64-native-alpha-default-recovery.json').read_text());before=hashlib.sha256(binary.read_bytes()).hexdigest();assert before==source['sha256']
directory=root/'outputs'/('native-alpha-'+uuid.uuid4().hex);directory.mkdir();oracle=directory/'oracle.bin'
for name,exe in [('native','probe_native_alpha_instructions.exe'),('x64','test_native_alpha_shadow_state.exe')]:
 run=subprocess.run([str(root/'work'/exe),str(oracle)],cwd=root,capture_output=True,text=True,timeout=60);log=run.stdout+run.stderr;(directory/(name+'.txt')).write_text(log);assert run.returncode==0,log;print(log.strip())
assert hashlib.sha256(binary.read_bytes()).hexdigest()==before
import struct,collections
sequence=Path(str(oracle)+'.sequence').read_bytes();assert len(sequence)==256+65536*268
sequence_counts=collections.Counter(struct.unpack_from('<I',sequence,256+i*268)[0] for i in range(65536));assert set(sequence_counts)==set(range(11))
default_trace=list(struct.iter_unpack('<III',Path(str(oracle)+'.default-call-trace').read_bytes()))
missing=0xffffffff
expected_default=[(1,3,missing),(2,1,missing),(3,1,missing),(6,1,missing),(7,0,missing),(12,0,missing),(8,0,missing),(9,0,0),(27,0,missing),(10,0,missing),(11,0,0),(28,0,missing),(13,6,0x3f333333),(14,2,2),(15,1,missing),(24,0,missing),(4,0,missing),(19,0,missing),(17,0,0),(18,0,0),(22,0,0),(23,0,missing)]
for stage in range(16):expected_default.extend([(21,stage,0),(20,stage,0)])
assert default_trace==expected_default
